import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"LLM-as-Code: Agentic Programming for Agent Harness","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.15874","title":"LLM-as-Code: Agentic Programming for Agent Harness","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.15874,"authors":["Junjia Qi","Zichuan Fu","Jingtong Gao","Wenlin Zhang","Hanyu Yan","Xian Wu","Xiangyu Zhao"],"domains":["cs.AI","cs.SE"],"html":"https://arxiv.org/html/2606.15874v2","pdf_path":"pdfs/2606.15874.pdf","published_date":"2026-06-14T00:00:00.000Z","venue":"KDD 2026 Workshop on Agentic Software Engineering"},"headers":[],"relativePath":"research/papers/2026-06-14-llm-as-code-agentic-programming-agent-harness-2606-15874.md","filePath":"research/papers/2026-06-14-llm-as-code-agentic-programming-agent-harness-2606-15874.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-14-llm-as-code-agentic-programming-agent-harness-2606-15874.md"};function s(i,e,l,c,g,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="llm-as-code-agentic-programming-for-agent-harness" tabindex="-1">LLM-as-Code: Agentic Programming for Agent Harness <a class="header-anchor" href="#llm-as-code-agentic-programming-for-agent-harness" aria-label="Permalink to &quot;LLM-as-Code: Agentic Programming for Agent Harness&quot;">​</a></h1><p><strong>Authors</strong>: Junjia Qi, Zichuan Fu, Jingtong Gao, Wenlin Zhang, Hanyu Yan, Xian Wu, Xiangyu Zhao <strong>Published</strong>: June 14, 2026 (v2: June 22, 2026) · Accepted at KDD 2026 Workshop on Agentic Software Engineering <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.15874" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.15874</a> · <a href="https://arxiv.org/html/2606.15874v2" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.15874 <strong>Categories</strong>: cs.AI, cs.SE <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.15874" target="_blank" rel="noreferrer">research/papers/pdfs/2606.15874.pdf</a> (7 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Every major LLM agent framework gives the LLM the role of orchestrator; the model decides what to do next, when to call tools, and when to stop. We argue that token explosion, control-flow hallucination, and unreliable completion are not implementation bugs but architectural consequences of assigning the deterministic work of looping, branching, and sequencing to a probabilistic system. A better prompt or a stronger model cannot guarantee the reliability of the LLM agent. We therefore propose Agentic Programming, in which the program governs all control flow, and the LLM is itself part of it, an adaptive component we call LLM-as-Code and invoke only where a task calls for reasoning or generation. Within each call the model keeps full flexibility, but it cannot alter the program&#39;s execution path. With control in the program, the LLM&#39;s context is built from the execution history&#39;s call tree and forms a directed acyclic graph (DAG). Each call&#39;s context length is then determined by its call depth rather than by accumulation over steps. A case study of computer-use agents shows that the design is practical, not just a theoretical stance, substantially improving the stability of long visual operation sequences.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>論點：token explosion、control-flow hallucination、unreliable completion <strong>不是 bug，而是「把 loop/branch/sequence 這類確定性工作交給機率系統」的架構後果</strong>——換更好 prompt / 更強模型都救不了。</p><ul><li><strong>Agentic Programming</strong>：由 <strong>program 掌管所有 control flow</strong>，LLM 只是其中可調用元件（<strong>LLM-as-Code</strong>），僅在需 reasoning/generation 時呼叫。</li><li>單次呼叫內模型保有完整彈性，但<strong>不能改變 program 的執行路徑</strong>。</li><li><strong>context 由執行歷史 call tree 構成 DAG</strong>：每次呼叫的 context 長度由 <strong>call depth</strong> 決定，而非隨步數累積 → 抑制 token 爆炸。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>computer-use agent case study：顯著提升長視覺操作序列的穩定性（abstract 未給具體數字）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>7 pp workshop 短文；僅單一 case study，缺跨領域定量評估。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>與 core.md 跨切紀律幾乎逐字對齊</strong>：「LLM 只做判斷、確定性代碼做決定（路由/重試/控制流）」= 本文「program 掌 control flow、LLM-as-Code 只做 reasoning」。最強外部背書之一。</li><li><strong>Workflow 工具的理論依據</strong>：本 workspace 的 dynamic Workflow（deterministic 控制流 + agent() 做判斷）正是 Agentic Programming 的實例；可作 multi-mode-skill / Workflow 設計論證引用。</li><li><strong>DAG context by call-depth = context-management.md NLAH</strong>：context 不隨步數累積、由結構決定——直接呼應「right context &gt; more context」與 prompt caching 紀律。</li><li>⚠️ code-as-harness（2605-18747）的延伸/激進版；列為 harness-engineering 控制流子線核心讀物。</li></ul>',17)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
